#include <iostream>
#include <iomanip>
#include <stdexcept>

class Time {
public:
    explicit Time(int hr = 0, int min = 0, int sec = 0) {
        setTime(hr, min, sec);
    }

    Time &setTime(int h, int m, int s) {
        setHour(h);
        setMinute(m);
        setSecond(s);
        return *this;
    }

    Time &setHour(int h) {
        if (h < 0 || h >= 24) {
            throw std::invalid_argument("hour must be 0-23");
        }
        hour = h;
        return *this;
    }

    Time &setMinute(int m) {
        if (m < 0 || m >= 60) {
            throw std::invalid_argument("minute must be 0-59");
        }
        minute = m;
        return *this;
    }

    Time &setSecond(int s) {
        if (s < 0 || s >= 60) {
            throw std::invalid_argument("second must be 0-59");
        }
        second = s;
        return *this;
    }

    void printUniversal() const {
        std::cout << std::setfill('0') << std::setw(2) << hour << ":"
                  << std::setfill('0') << std::setw(2) << minute << ":"
                  << std::setfill('0') << std::setw(2) << second;
    }

    void printStandard() const {
        std::cout << ((hour == 0 || hour == 12) ? 12 : hour % 12) << ":"
                  << std::setfill('0') << std::setw(2) << minute << ":"
                  << std::setfill('0') << std::setw(2) << second
                  << (hour < 12 ? " AM" : " PM");
    }

private:
    int hour{0};
    int minute{0};
    int second{0};
};

int main() {
    Time t;
    t.setHour(18).setMinute(30).setSecond(22);

    std::cout << "Universal time: ";
    t.printUniversal();
    std::cout << "\nStandard time: ";
    t.printStandard();

    std::cout << "\n\nNew standard time: ";
    t.setTime(20, 20, 20).printStandard();
    std::cout << '\n';

    return 0;
}

#include <iostream>
#include <string>

class Employee {
public:
    Employee(const std::string &first, const std::string &last)
        : firstName(first), lastName(last) {
        ++count;
        std::cout << "Employee constructor for " << firstName << " " << lastName << " called.\n";
    }

    ~Employee() {
        std::cout << "~Employee() called for " << firstName << " " << lastName << "\n";
        --count;
    }

    std::string getFirstName() const { return firstName; }
    std::string getLastName() const { return lastName; }

    // Static member function has no 'this' pointer and cannot be const
    static unsigned int getCount() {
        return count;
    }

private:
    std::string firstName;
    std::string lastName;

    // C++17 inline static data member initialized directly in-class
    inline static unsigned int count{0};
};

int main() {
    std::cout << "Number of employees before instantiation: "
              << Employee::getCount() << '\n';

    {
        Employee e1("Susan", "Baker");
        Employee e2("Robert", "Jones");

        std::cout << "Number of employees after instantiation: "
                  << Employee::getCount() << "\n\n";

        std::cout << "Employee 1: " << e1.getFirstName() << " " << e1.getLastName() << '\n';
        std::cout << "Employee 2: " << e2.getFirstName() << " " << e2.getLastName() << "\n\n";
    } // e1 and e2 destructed here

    std::cout << "Number of employees after objects are destroyed: "
              << Employee::getCount() << '\n';

    return 0;
}
